SELECT COUNT(*) FROM classroom_events e
JOIN classroom_sessions s ON s.id = e.session_id
WHERE s.user_id = #{userId}

SELECT COALESCE(SUM(COALESCE(actual_tokens, estimated_tokens)), 0)
FROM ai_quota_reservations
WHERE user_id = #{userId} AND completed_at IS NOT NULL AND quota_date >= #{since}

SELECT COUNT(*)
FROM ai_quota_reservations
WHERE user_id = #{userId} AND completed_at IS NOT NULL AND quota_date >= #{since}
